\begin{aligned}
\delta(s_0, v_{k_0}) &= \min\bigl(\{\delta(s_0, u_{k_0-1}) + w(u_{k_0-1}, v_{k_0}) \mid u_{k_0-1} \in Adj^-(v_{k_0})\} \cup \{\delta(s_0, v_{k_0-1})\}\bigr) \\
&= \min\bigl(\{\delta_{k_0-1}(s, u) + w(u, v) \mid u \in Adj^-(v)\} \cup \{\delta_{k_0-1}(s, v)\}\bigr) \quad \text{(by induction)} \\
&= \delta_{k_0}(s, v)
\end{aligned}

\begin{aligned}
d(s, y) &\le \delta(s, x) + w(x, y) && \text{取出 } x \text{ 时 relax 了 edge } (x, y) \\
&= \delta(s, y) && \text{shortest path 的 subpath 仍是 shortest path} \\
&\le \delta(s, v_0) && \text{edge weights 非负} \\
&\le d(s, v_0) && \text{relaxation 是 safe 的} \\
&\le d(s, y) && v_0 \text{ 是 } Q \text{ 中 } d(s, v_0) \text{ 最小的 vertex}
\end{aligned}

